        | { isSkeleton: true; text?: ReactNode }
        | { isSkeleton?: false; text: ReactNode }
    )

const TypographyBase = ({
    text,
    color,
    weight,
    isItalic,
    isStruck,
    isLink,
    isButton = false,
    hoverColor,
    underlineOnGroupHover = false,
    underlineOnHover = false,
    parseInlineCode = false,
    href,
    target,
    rel,
    onPress,
    prefixIcon: Prefix,
    suffixIcon: Suffix,
    iconSlide = false,
    truncate = false,
    lineClamp,
    noWrap = false,
    preserveWhitespace = false,
    isInline = false,
    align,
    tabularNums = false,
    isSkeleton = false,
    classNames,
    size = "base",
}: TypographyProps) => {
    // Node name = the REAL component being rendered in that branch (not a role word):
    // heading/code/link branches wrap a HeroUI component, so the default name must say
    // which one — "Text" would hide that a `Typography.Heading`/`Typography`/`Link` is
    // actually on screen. The plain body span isn't wrapping any named component, so it
    // keeps the generic "Text" default.
    // The name is written at each branch rather than through a helper. A helper here is invisible
    // to every tool that strips the overlay by token — its own name says nothing about anatomy —
    // so it survives into the app's copy as a call to something that no longer exists.
    const renderedText = parseInlineCode && typeof text === "string" ? renderInlineCode(text) : text

    // ── SKELETON branch — checked BEFORE any size branch, because heading/code also
    // need to render a shimmer bar, not empty text. (If placed under the heading branch,
    // `size="h3" isSkeleton` would render an EMPTY heading — a silent bug tsc/eslint won't catch.)
    if (isSkeleton) {
        return (
            <HeroSkeleton
                data-tier="atom"
                data-component="Typography"
                className={cn("inline-block w-1/2 rounded", SKEL_H[size], classNames)}
            />
        )
    }

    // ── HEADING branch: wraps the HeroUI compound `Typography.Heading`.
    if (size in HEADING_LEVEL) {
        return (
            <HeroTypography.Heading
                data-tier="atom"
                data-component="Typography"
                level={HEADING_LEVEL[size]}
                weight={weight}
                className={cn(
                    COLOR_CLS[color ?? "default"],
                    align ? ALIGN_CLS[align] : null,
                    lineClamp ? CLAMP_CLS[lineClamp] : truncate ? "block truncate" : null,
                    noWrap && NO_WRAP_CLS,
                    preserveWhitespace && PRESERVE_WHITESPACE_CLS,
                    isInline && INLINE_CLS,
                    underlineOnGroupHover && GROUP_HOVER_UNDERLINE_CLS,
                    classNames,
                )}
            >
                {renderedText}
            </HeroTypography.Heading>
        )
    }

    // ── CODE branch
    if (size === "code") {
        return (
            <HeroTypography
                data-tier="atom"
                data-component="Typography"
                type="code"
                className={cn(
                    COLOR_CLS[color ?? "default"],
                    align ? ALIGN_CLS[align] : null,
                    lineClamp ? CLAMP_CLS[lineClamp] : truncate ? "block truncate" : null,
                    noWrap && NO_WRAP_CLS,
                    preserveWhitespace && PRESERVE_WHITESPACE_CLS,
                    isInline && INLINE_CLS,
                    underlineOnGroupHover && GROUP_HOVER_UNDERLINE_CLS,
                    classNames,
                )}
            >
                {renderedText}
            </HeroTypography>
        )
    }

    // ── BODY branch (xs/sm/base/lg) — built with classes
    const bodySize = size as Size
    {
        if (isSkeleton) {
            return (
                <HeroSkeleton
                    data-tier="atom"
                    data-component="Typography"
                    className={cn("inline-block w-1/2 rounded", SKEL_H[bodySize], classNames)}
                />
            )
        }

        // isLink → HeroUI Link (leverages HeroUI: hover underline + a11y). Separate state.
        // Color defaults to accent; an explicit `color` overrides it (e.g. a muted
        // external-source link that inherits its row's tone). `underlineOnHover` swaps
        // the plain default underline for the quiet recipe (see its own prop doc).
        if (isLink) {
            return (
                <HeroLink
                    data-tier="atom"
                    data-component="Typography"
                    href={href}
                    target={target}
                    rel={rel}
                    onPress={onPress}
                    className={cn(
                        TEXT_CLS[bodySize],
                        color ? COLOR_CLS[color] : "text-accent",
                        "cursor-pointer",
                        underlineOnHover ? SELF_HOVER_UNDERLINE_CLS : "underline-offset-2 hover:underline",
                        classNames,
                    )}
                >
                    {renderedText}
                </HeroLink>
            )
        }

        // isButton → a plain pressable button: text that DOES something but is not
        // navigation. No underline (unlike isLink) — only an optional hover color shift.
        if (isButton) {
            return (
                <button
                    data-tier="atom"
                    data-component="Typography"
                    type="button"
                    onClick={onPress}
                    className={cn(
                        TEXT_CLS[bodySize],
                        // `semibold` folds to `font-medium` at body scale — a real third
                        // tier only at heading scale (see the HEADING branch above).
                        weight === "bold" ? "font-bold" : weight === "medium" || weight === "semibold" ? "font-medium" : null,
                        COLOR_CLS[color ?? "default"],
                        "cursor-pointer transition-colors",
                        hoverColor && HOVER_COLOR_CLS[hoverColor],
                        classNames,
                    )}
                >
                    {renderedText}
                </button>
            )
        }

        const hasIcons = Boolean(Prefix || Suffix)
        // Has icon → text is forced to `font-medium` (icon strokes fit medium text
        // better). `semibold` folds to `font-medium` at body scale — a real third tier
        // only at heading scale (see the HEADING branch above).
        //
        // The "no weight" branch emits `font-normal` explicitly rather than no class:
        // HeroUI's own `.accordion__trigger { font-medium }` bleeds into unstyled text
        // nested inside it, so leaving this unset lets an ancestor's font-weight silently win.
        const weightCls = hasIcons
            ? "font-medium"
            : weight === "bold" ? "font-bold" : weight === "medium" || weight === "semibold" ? "font-medium" : "font-normal"
        // Clip text: lineClamp wins over truncate. `block` so overflow can clip (needs a bounded parent width).
        const clampCls = lineClamp ? CLAMP_CLS[lineClamp] : truncate ? "block truncate" : null
        const baseCls = cn(
            TEXT_CLS[bodySize],
            weightCls,
            isItalic && "italic",
            isStruck && "line-through",
            COLOR_CLS[color ?? "default"],
            align ? ALIGN_CLS[align] : null,
            tabularNums && "tabular-nums",
            noWrap && NO_WRAP_CLS,
            preserveWhitespace && PRESERVE_WHITESPACE_CLS,
            isInline && INLINE_CLS,
            underlineOnGroupHover && GROUP_HOVER_UNDERLINE_CLS,
            classNames,
        )

        if (hasIcons) {
            // One discriminator, not two. `side` decides both the part name and which way the glyph
            // slides, so the two can never be handed each other's value — and because it still earns
            // its keep with the overlay stripped, the app's copy keeps the same signature.
            const iconSpan = (Icon: TypographyIcon, side: "Prefix" | "Suffix") => (
                // Atom owns the glyph scale — icon inherits currentColor (matches text tone).
                <span
                    aria-hidden
                    // Tailwind v4: `translate` is its OWN CSS property → the transition must target
                    // `translate` (not `transform`), otherwise hover will jump ([[tailwind-v4-scale-is-own-property]]).
                    className={cn(
                        "inline-flex shrink-0",
                        iconSlide && "transition-[translate] duration-200 ease-out",
                        iconSlide && (side === "Prefix" ? "group-hover:-translate-x-1" : "group-hover:translate-x-1"),
                    )}
                >
                    <Icon className={ICON_CLS[bodySize]} weight={ICON_WEIGHT[bodySize]} />
                </span>
            )
            return (
                // `group` so the child arrow can hear `group-hover` when iconSlide is on.
                <span data-tier="atom" data-component="Typography" className={cn("inline-flex items-center gap-1", iconSlide && "group", baseCls)}>
                    {Prefix ? iconSpan(Prefix, "Prefix") : null}
                    <span className={cn("min-w-0", clampCls)}>{renderedText}</span>
                    {Suffix ? iconSpan(Suffix, "Suffix") : null}
                </span>
            )
        }
        return (
            <span data-tier="atom" data-component="Typography" className={cn(baseCls, clampCls)}>
                {renderedText}
            </span>
        )
    }
}

/** `Typography` — text atom: one component, one `size` prop spanning body, heading, and code scales. */
export { TypographyBase as Typography }

/** Tier metadata for `Typography`, used by the component registry/Storybook lookup. */
export const meta = { tier: "atom", name: "Typography" } as const

import React from "react"
import type { ReactNode } from "react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Divider } from "@/components/atoms/display/Divider"
import { type AllowedGap, type LayoutAlign, type LayoutJustify, type PaddingValue, type Responsive } from "@/components/frames/_spacing"
import { Flex } from "@/components/frames/Flex"
import type { ResponsiveRowSwitch } from "@/components/frames/ResponsiveRow"
import type { PrincipleToken, ExplainReason } from "@/components/frames/_principles"
import type { CallerIdentity } from "@/components/frames/_identity"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * LAYOUT (frame) -- `Stack.*`: the base one-axis track. Two members = two AXES,
 * the only real shapes a stack has:
 *   • `StackV` -- stacks VERTICALLY (column).
 *   • `StackH` -- stacks HORIZONTALLY (row); only this axis takes `at` (FRAME-10:
 *     the container step it wraps below, never a bare boolean).
 *
 * FRAME API LAW (§13b): a stack WRAPS arbitrary content -- it is not a repeating
 * list -- so `children` is the road (there is no `header`/`body`/`footer` trio to
 * name: a track has exactly ONE slot, its content). `items` would be wrong here;
 * see `Cluster`/`Grid` for the repeat-list frames of this folder.
 *
 * WHY THIS FRAME EXISTS: `gap` is typed {@link Responsive}<{@link AllowedGap}> -- a
 * CLOSED index into the house gap table. Off-scale (`gap-4.5`, `gap-[13px]`) cannot even
 * be typed, so the scale is enforced by the COMPILER instead of by review.
 * `gap` is REQUIRED for the same reason: an implicit default would let the seam
 * be chosen by accident, and §10a says a seam has exactly one deliberate owner.
 *
 * §13 boundaries respected: no domain content, no feature behaviour -- the track
 * only decides direction / gap / alignment / an optional rule between children.
 * `divider` COMPOSES the existing `Divider` atom (§13c: a frame never
 * hand-rolls what an atom already owns).
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Props shared by both axes of {@link Stack}. */
export interface StackBaseProps {
    /**
     * Seam between children on the house gap scale.
     * Optional when `principle` is a gap-owning token — the principle resolves the class.
     * Still required when there is no gap principle (Flex enforces at render via ownership).
     */
    gap?: Responsive<AllowedGap>
    /** Cross-axis alignment (`V` → horizontal, `H` → vertical). */
    align?: LayoutAlign
    /** Main-axis distribution (`V` → vertical, `H` → horizontal). */
    justify?: LayoutJustify
    /** `true` → inserts `Divider` BETWEEN children (never before the first / after the last). */
    divider?: boolean
    /**
     * Space INSIDE the track, same scale as `gap`.
     *
     * 2026-07-27: forwarded down to `Flex` so a stack that also needs padding no longer
     * has to DROP to `Flex` and lose `divider` plus the axis semantics. That drop was the
     * one remaining reason to reach past this frame, and a way out that costs less than the
     * proper road always wins -- the same force that produced 227 hand-written
     * `flex flex-col gap-4` in the first place.
     */
    padding?: Responsive<PaddingValue>
    /**
     * `true` → a left guide border + matching indent (`pl-3`, `@app-sm:pl-6`),
     * for a track that is ONE LEVEL DEEPER than its caller (a threaded reply,
     * a nested tree row) -- the frame owns the exact classes so no block ever
     * hand-writes `border-l`/`pl-*` itself (teacher 2026-07-28). Same vocabulary
     * as `SurfaceCard`'s own `variant="nested"` (border marks "inside a
     * parent", not a fresh outer face) -- this is that same idea for a track.
     */
    nested?: boolean
    /**
     * The HTML element to render, forwarded to `Flex`. Defaults to `div`.
     *
     * Added 2026-07-29 for the same reason `padding` was: a stack that also needed a real tag
     * (`section`, `figure`, `span`) had to DROP to hand-written classes and lose the axis
     * semantics along the way. Three call-sites sat outside the frame tier for exactly that.
     */
    as?: "div" | "section" | "figure" | "span" | "li"
    /**
     * `true` → the track hugs its content (`inline-flex`) instead of taking the whole line.
     * Measured on the same content: the block box came out 503px, the inline box 136px.
     */
    inline?: boolean
    /**
     * Anatomy tag for THIS frame itself -- so the PARENT can badge it as ONE node (§11a.1).
     * Missing this prop means the `layouts`-tier frame is used but the panel cannot see it.
     */
    /** A SINGLE buildable child -- an uncalled `ComponentType<{isSkeleton?}>` the track renders itself. Use `items` for several. */
    body?: ComponentTypeWithSkeleton
    /**
     * The stacked content as BUILDABLE items -- each an uncalled `ComponentType<{isSkeleton?}>`
     * the track renders itself, so it can thread `isSkeleton` down and interleave dividers. Preferred
     * over `body`: a frame that can BUILD its children can shimmer them (one tree, no hand-mirror).
     * Wins over `body` when both are passed.
     */
    items?: Array<ComponentTypeWithSkeleton>
    /** `true` → the track passes `isSkeleton` to every `items` component so the whole column shimmers. */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable -- it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * The layout pattern this track's seam realises - forwarded straight to the `Flex` this
     * track renders through, the same way `gap`/`align`/`justify` are. See `Flex`'s own
     * `pattern` doc for the full contract. Query as `[data-principle="token"]`.
     */
    principle?: PrincipleToken
    /**
     * Why this layer exists - one sentence, emitted as `data-explain` beside the token.
     * A reason, never a restatement of `principle`. Forwarded to `Flex`.
     */
    explain?: ExplainReason
    /**
     * Caller identity to wear on this track's root instead of `Stack`'s own -- pass this when a
     * `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its own) is
     * using this track AS its root element, instead of wrapping it in a raw `<div data-tier=...
     * data-component=...>`. Forwarded straight to `Flex`, which is what actually renders the DOM
     * (see `Flex`'s own `identity` doc). See `_identity.ts`. Omitted → this track keeps
     * emitting `data-tier="frame" data-component="Flex"`, unchanged.
     */
    identity?: CallerIdentity
}

/** Props for {@link StackV} -- a vertical track (no row-only prop to add). */
export type StackVProps = StackBaseProps

/** Props for {@link StackH} -- a horizontal track. */
export interface StackHProps extends StackBaseProps {
    /**
     * Container step the row switches from wrapped to single-line at (FRAME-10). Below `at`
     * children flow onto a new line when the row runs out of width; at `at` and above the row
     * stays single-line. ROW-ONLY: a column already grows without bound, so this is meaningless
     * on `StackV` and is not offered there. Left out, the row never wraps -- same behaviour the
     * old `wrap={false}` default had.
     */
    at?: ResponsiveRowSwitch
}

/**
 * Interleaves `Divider` between children -- NOT around them: N children get
 * N−1 rules. The atom carries its own `` (part name `Line`), so the
 * frame adds no wrapper element and the DOM is identical with badges on or off.
 *
 * On a ROW the rule is vertical and gets `self-stretch`: `align-self` overrides
 * the track's `items-*`, so the line spans the row's full height even when the
 * row is `items-center`.
 */
const interleaveDividers = (children: ReactNode, axis: "vertical" | "horizontal") => {
    const nodes = React.Children.toArray(children)
    // `axis` = the TRACK's direction; a rule always runs ACROSS it.
    const ruleOrientation = axis === "vertical" ? "horizontal" : "vertical"
    return nodes.flatMap((child, index) =>
        index === 0
            ? [child]
            : [
                <Divider
                    key={`stack-divider-${index}`}
                    orientation={ruleOrientation}
                    classNames={ruleOrientation === "vertical" ? ["self-stretch"] : undefined}
                />,
                child,
            ],
    )
}

/**
 * Vertical track -- the default way to stack anything down a column.
 *
 * @param props - {@link StackVProps}
 */
const StackV = ({
    as: Tag,
    inline,
    gap,
    align = "stretch",
    justify,
    divider = false,
    nested = false,
    body,
    items,
    isSkeleton,
    padding,
    classNames,
    principle,
    explain,
    identity}: StackVProps) => {
    // `items` (buildable) wins over legacy `body`: the track renders each item itself, threading
    // `isSkeleton`, so it can shimmer the whole column and interleave dividers on the real children.
    const content = (items ?? (body ? [body] : [])).map((Item, index) => <Item key={index} isSkeleton={isSkeleton} />)
    // Strict contract: when `principle` is set it owns the full CSS — do not forward
    // gap/padding/align/justify/classNames/inline/nested from the caller.
    if (principle) {
        return (
            <Flex
                as={Tag}
                direction="col"
                principle={principle}
                explain={explain}
                identity={identity}
                body={divider ? interleaveDividers(content, "vertical") : content}
            />
        )
    }
    return (
        <Flex
            as={Tag}
            inline={inline}
            direction="col"
            gap={gap}
            padding={padding}
            align={align}
            justify={justify}
            nested={nested}
            classNames={classNames}
            identity={identity}
            body={divider ? interleaveDividers(content, "vertical") : content}
        />
    )
}

const StackH = ({
    as: Tag,
    inline,
    gap,
    align = "center",
    justify,
    at,
    divider = false,
    nested = false,
    body,
    items,
    isSkeleton,
    padding,
    classNames,
    principle,
    explain,
    identity}: StackHProps) => {
    const content = (items ?? (body ? [body] : [])).map((Item, index) => <Item key={index} isSkeleton={isSkeleton} />)
    if (principle) {
        return (
            <Flex
                as={Tag}
                direction="row"
                principle={principle}
                explain={explain}
                identity={identity}
                // `at` is a named width switch (FRAME-10), not a free CSS boolean — still forwarded.
                at={at}
                body={divider ? interleaveDividers(content, "horizontal") : content}
            />
        )
    }
    return (
        <Flex
            as={Tag}
            inline={inline}
            direction="row"
            gap={gap}
            padding={padding}
            align={align}
            justify={justify}
            at={at}
            nested={nested}
            classNames={classNames}
            identity={identity}
            body={divider ? interleaveDividers(content, "horizontal") : content}
        />
    )
}

export { StackV, StackH }

/**
 * Source-level tier marker -- lets a gate read the tier without guessing from the folder path.
 *
 * Shaped as a record, not the single `{ tier, name }` most frame files export: this file has
 * TWO public components, not one, and neither is more "the" component this file names. See
 * `Flex`'s own `meta` note for the DOM side of this -- `StackV`/`StackH` render no element
 * of their own (100% delegated to `Flex`), so `data-component` on a rendered Stack instance
 * reads `"Flex"`, not `"StackV"`/`"StackH"`; this export is the source-level identity, which a
 * gate can still read even though the DOM cannot show it.
 */
export const meta = {
    StackV: { tier: "frame", name: "StackV" },
    StackH: { tier: "frame", name: "StackH" },
} as const
